using IMed.Api.Domain.Diagrams;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace IMed.Api.Infrastructure.Persistence.Seeding;

/// <summary>
/// Seeder de <see cref="DiagramDefinition"/> con presets globales (organization_id = null).
/// Mismo patrón upsert-por-code que <see cref="FormDefinitionsSeeder"/> — ver ahí el
/// razonamiento completo (tolera tabla no creada aún, sólo inserta codes faltantes).
///
/// <para>El preset "odontograma" fue extraído tal cual del componente Angular
/// (<c>fhir-client/src/app/features/odontology/data/odontogram-sample.ts</c>) — el
/// SVG y las 192 zonas (32 piezas × corona + 5 superficies) son exactamente los
/// mismos que ya usa el frontend, para que no exista divergencia entre lo que
/// se ve en <c>OdontogramDemoPage</c> y lo que sirve este endpoint.</para>
///
/// <para><c>linked_form_codes_json</c> referencia por <c>code</c> a tres
/// <see cref="Domain.Forms.FormDefinition"/> registrados en
/// <c>FormDefinitionsSeeder</c> (<c>odonto-caries</c>, <c>odonto-endodoncia</c>,
/// <c>odonto-extraccion</c>) — sin <c>specialtyCode</c> propio a propósito, para
/// que no interfieran con la resolución por especialidad del form clínico
/// "odontologia"; sólo se resuelven por code exacto desde acá.</para>
/// </summary>
public sealed class DiagramDefinitionsSeeder(
    IServiceScopeFactory scopeFactory,
    TimeProvider timeProvider,
    ILogger<DiagramDefinitionsSeeder> logger) : IHostedService
{
    private static readonly Guid SystemSeederId = new("00000000-0000-0000-0000-000000000001");

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        try
        {
            await using var scope = scopeFactory.CreateAsyncScope();
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();

            bool hasGlobalPresets;
            try
            {
                hasGlobalPresets = await db.DiagramDefinitions
                    .AnyAsync(x => x.OrganizationId == null, cancellationToken);
            }
            catch (Exception)
            {
                logger.LogWarning("Tabla diagram_definitions aún no existe; ejecutando migrate y reintentando.");
                await db.Database.MigrateAsync(cancellationToken);
                hasGlobalPresets = await db.DiagramDefinitions
                    .AnyAsync(x => x.OrganizationId == null, cancellationToken);
            }

            var presets = BuildPresets();

            if (!hasGlobalPresets)
            {
                foreach (var preset in presets)
                {
                    preset.Publish(SystemSeederId, timeProvider);
                }
                db.DiagramDefinitions.AddRange(presets);
                await db.SaveChangesAsync(cancellationToken);
                logger.LogInformation("DiagramDefinitions seed inicial: {Count} presets globales insertados.", presets.Length);
                return;
            }

            var existingCodes = await db.DiagramDefinitions
                .Where(x => x.OrganizationId == null)
                .Select(x => x.Code)
                .ToListAsync(cancellationToken);

            var missing = presets.Where(p => !existingCodes.Contains(p.Code)).ToArray();
            if (missing.Length == 0)
            {
                logger.LogDebug("DiagramDefinitions seed: todos los presets globales ya existen; skip.");
                return;
            }

            foreach (var preset in missing)
            {
                preset.Publish(SystemSeederId, timeProvider);
            }
            db.DiagramDefinitions.AddRange(missing);
            await db.SaveChangesAsync(cancellationToken);
            logger.LogInformation("DiagramDefinitions seed: {Count} preset(s) nuevo(s) insertado(s): {Codes}.",
                missing.Length, string.Join(", ", missing.Select(p => p.Code)));
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            logger.LogError(ex, "DiagramDefinitionsSeeder falló; presets globales pueden no estar disponibles.");
        }
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;

    private DiagramDefinition[] BuildPresets()
    {
        return
        [
            DiagramDefinition.CreateDraft(
                code: "odontograma",
                title: "Odontograma (FDI)",
                description: "Odontograma interactivo de 32 piezas dentales (notación FDI) con vista coronal y 5 superficies oclusales por diente (192 zonas).",
                svgContent: OdontogramaSvg,
                zonesJson: OdontogramaZonesJson,
                createdBy: SystemSeederId,
                // SNOMED 722163006 = Odontología general (mismo code que el FormDefinition "odontologia").
                specialtyCode: "722163006",
                annotationStyleJson: OdontogramaAnnotationStyleJson,
                linkedFormCodesJson: """["odonto-caries","odonto-endodoncia","odonto-extraccion"]""",
                zoneBodySiteMapJson: OdontogramaZoneBodySiteMapJson,
                organizationId: null,
                version: "1.0.0",
                timeProvider: timeProvider),
        ];
    }

